using System.Data;
using System.Security.Claims;
using FIXIT.API.Contracts;
using FIXIT.Domain.Entities;
using FIXIT.Infrastructure;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace FIXIT.API.Controllers;
[ApiController,Route("api/admin"),Authorize(Roles="Administrator")]
public class AdminController(FIXITDbContext db,UserManager<User> users,IWebHostEnvironment env):ControllerBase
{
 string Actor=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 [HttpGet("dashboard")]
 public async Task<IActionResult> Dashboard()
 {
     var status=await db.Bookings.AsNoTracking().GroupBy(b=>b.Status).Select(g=>new{status=g.Key.ToString(),count=g.Count()}).ToListAsync();
     var paid=db.Payments.AsNoTracking().Where(p=>p.Status==PaymentStatus.Paid);
     var gross=await paid.SumAsync(p=>(decimal?)p.Amount)??0m;
     var platformFees=await paid.SumAsync(p=>(decimal?)p.PlatformFeeAmount)??0m;
     var technicianEarnings=await paid.SumAsync(p=>(decimal?)p.TechnicianEarnings)??0m;
     var fee=(await db.PlatformSettings.FindAsync("PlatformFeePercent"))?.NumericValue??15m;
     var activity=await db.AuditLogs.AsNoTracking().OrderByDescending(a=>a.CreatedAt).Take(12).ToListAsync();
     var customerCount=(await users.GetUsersInRoleAsync("Customer")).Count;
     var technicianCount=(await users.GetUsersInRoleAsync("Technician")).Count;
     return Ok(new{customers=customerCount,technicians=technicianCount,pendingVerification=await db.TechnicianProfiles.CountAsync(t=>t.Status==TechnicianStatus.Pending),activeBookings=await db.Bookings.CountAsync(b=>b.Status==BookingStatus.Accepted||b.Status==BookingStatus.EnRoute||b.Status==BookingStatus.Arrived||b.Status==BookingStatus.InProgress),completed=await db.Bookings.CountAsync(b=>b.Status==BookingStatus.Completed),cancelled=await db.Bookings.CountAsync(b=>b.Status==BookingStatus.Cancelled),grossBookingValue=gross,platformFees,technicianEarnings,platformFeePercent=fee,status,activity});
 }
 [HttpGet("technicians/pending")] public async Task<IActionResult> Pending()=>Ok(await db.TechnicianProfiles.AsNoTracking().Where(p=>p.Status==TechnicianStatus.Pending).Select(p=>new{p.UserId,name=p.User.FirstName+" "+p.User.LastName,p.User.Email,p.User.PhoneNumber,services=p.TechnicianSkills.Select(s=>s.Service.Name).ToList(),p.Skills,coverageAreas=p.TechnicianCoverageAreas.Select(a=>a.ServiceArea.CityMunicipality+", "+a.ServiceArea.Province).ToList(),p.Status}).ToListAsync());
 [HttpGet("technicians")] public async Task<IActionResult> Technicians()=>Ok(await db.TechnicianProfiles.AsNoTracking().Where(p=>p.Status==TechnicianStatus.Approved&&p.IsOnline&&p.User.IsActive).Select(p=>new{id=p.UserId,name=p.User.FirstName+" "+p.User.LastName,coverageAreas=p.TechnicianCoverageAreas.Select(a=>a.ServiceArea.CityMunicipality+", "+a.ServiceArea.Province).ToList(),services=p.TechnicianSkills.Select(s=>s.Service.Name).ToList()}).ToListAsync());
 [HttpPost("technicians/{id}/decision")] public async Task<IActionResult> DecideTechnician(string id,TechnicianDecisionRequest r){var p=await db.TechnicianProfiles.SingleOrDefaultAsync(x=>x.UserId==id);if(p is null)return NotFound();if(r.Approve&&(!await db.TechnicianSkills.AnyAsync(x=>x.TechnicianId==id)||!await db.TechnicianCoverageAreas.AnyAsync(x=>x.TechnicianId==id)))return BadRequest(new{message="The technician must select at least one service category and submit coverage areas before approval."});if(r.Approve&&!await db.VerificationRecords.AnyAsync(x=>x.TechnicianId==id&&x.Status==VerificationStatus.Approved))return BadRequest(new{message="Review and approve at least one verification document before approving this technician."});p.Status=r.Approve?TechnicianStatus.Approved:TechnicianStatus.Rejected;p.DecisionReason=r.Reason.Trim();p.ReviewedAt=DateTime.UtcNow;db.AuditLogs.Add(new(){ActorId=Actor,Action=r.Approve?"technician.approve":"technician.reject",EntityType="TechnicianProfile",EntityId=id,Details=r.Reason});db.Notifications.Add(new(){UserId=id,Title="Technician application reviewed",Message=$"Your FIXIT technician application was {p.Status.ToString().ToLowerInvariant()}. {r.Reason}"});await db.SaveChangesAsync();return Ok(new{status=p.Status.ToString()});}
 [HttpGet("verification")] public async Task<IActionResult> Verification()=>Ok(await db.VerificationRecords.AsNoTracking().OrderBy(x=>x.Status).ThenBy(x=>x.SubmittedAt).Select(x=>new{x.Id,x.TechnicianId,name=x.Technician.FirstName+" "+x.Technician.LastName,x.DocumentType,status=x.Status.ToString(),x.DecisionReason,x.SubmittedAt}).ToListAsync());
 [HttpGet("verification/{id:int}/document")] public async Task<IActionResult> VerificationDocument(int id){var record=await db.VerificationRecords.SingleOrDefaultAsync(x=>x.Id==id);if(record is null)return NotFound();db.AuditLogs.Add(new(){ActorId=Actor,Action="verification.document.view",EntityType="VerificationRecord",EntityId=id.ToString()});await db.SaveChangesAsync();var path=Path.Combine(env.ContentRootPath,"PrivateUploads",Path.GetFileName(record.PrivateStorageKey));if(!System.IO.File.Exists(path))return NotFound();var type=Path.GetExtension(path).ToLowerInvariant() switch{".pdf"=>"application/pdf",".jpg"=>"image/jpeg",_=>"image/png"};return PhysicalFile(path,type,$"verification-{id}{Path.GetExtension(path)}");}
 [HttpPost("verification/{id:int}/decision")] public async Task<IActionResult> VerificationDecision(int id,VerificationDecisionRequest r){var v=await db.VerificationRecords.SingleOrDefaultAsync(x=>x.Id==id);if(v is null)return NotFound();v.Status=r.Approve?VerificationStatus.Approved:VerificationStatus.Rejected;v.DecisionReason=r.Reason.Trim();v.ReviewedById=Actor;v.ReviewedAt=DateTime.UtcNow;db.AuditLogs.Add(new(){ActorId=Actor,Action=r.Approve?"verification.approve":"verification.reject",EntityType="VerificationRecord",EntityId=id.ToString(),Details=r.Reason});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("users")] public async Task<IActionResult> Users([FromQuery]string? search){var q=db.Users.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(u=>u.Email!.Contains(search)||u.FirstName.Contains(search)||u.LastName.Contains(search));return Ok(await q.OrderBy(u=>u.Email).Take(100).Select(u=>new{id=u.Id,u.Email,u.FirstName,u.LastName,u.PhoneNumber,u.IsActive,u.CreatedAt}).ToListAsync());}
 [HttpGet("administrators")] public async Task<IActionResult> Administrators(){var admins=await users.GetUsersInRoleAsync("Administrator");return Ok(admins.OrderBy(x=>x.Email).Select(x=>new{id=x.Id,x.Email,x.FirstName,x.LastName,x.IsActive,x.CreatedAt}));}
 [HttpPost("administrators")] public async Task<IActionResult> CreateAdministrator(AdministratorCreateRequest request){if(await users.FindByEmailAsync(request.Email) is not null)return Conflict(new{message="An account with that email already exists."});await using var transaction=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);var admin=new User{UserName=request.Email.Trim(),Email=request.Email.Trim(),EmailConfirmed=true,FirstName=request.FirstName.Trim(),LastName=request.LastName.Trim()};var created=await users.CreateAsync(admin,request.Password);if(!created.Succeeded)return BadRequest(new{message="Administrator account was not created. Check the email and password requirements."});var role=await users.AddToRoleAsync(admin,"Administrator");if(!role.Succeeded)return BadRequest(new{message="Unable to assign the administrator role."});db.AuditLogs.Add(new(){ActorId=Actor,Action="administrator.create",EntityType="User",EntityId=admin.Id,Details="Created administrator account: "+admin.Email});await db.SaveChangesAsync();await transaction.CommitAsync();return CreatedAtAction(nameof(Administrators),new{id=admin.Id},new{id=admin.Id,admin.Email,admin.FirstName,admin.LastName,admin.IsActive});}
 [HttpPut("users/{id}/status")] public async Task<IActionResult> UserStatus(string id,UserStatusRequest r){var u=await users.FindByIdAsync(id);if(u is null)return NotFound();if(id==Actor)return BadRequest(new{message="You cannot suspend your own administrator account."});u.IsActive=r.Active;await users.UpdateAsync(u);await users.UpdateSecurityStampAsync(u);db.AuditLogs.Add(new(){ActorId=Actor,Action=r.Active?"user.activate":"user.suspend",EntityType="User",EntityId=id,Details=r.Reason});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("bookings")] public async Task<IActionResult> Bookings([FromQuery]BookingStatus? status)=>Ok(await db.Bookings.AsNoTracking().Where(b=>status==null||b.Status==status).OrderByDescending(b=>b.CreatedAt).Take(200).Select(b=>new{id=b.Id,b.Reference,status=b.Status.ToString(),b.ScheduledAt,b.EstimatedTotal,customer=b.Customer.Email,technician=b.Technician==null?null:b.Technician.Email,service=b.Service.Name,city=b.Address.CityMunicipality}).ToListAsync());
 [HttpPost("bookings/{id:int}/assign")]
 public async Task<IActionResult> Assign(int id, AssignmentRequest request)
 {
     if (string.IsNullOrWhiteSpace(request.Reason)) return BadRequest(new { message = "Record a reason for this assignment." });
     await using var transaction = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);
     var booking = await db.Bookings.Include(x => x.Address).SingleOrDefaultAsync(x => x.Id == id);
     if (booking is null) return NotFound();
     if (booking.Status is not (BookingStatus.Pending or BookingStatus.Accepted))
         return Conflict(new { message = "Only pending or accepted bookings can be assigned or reassigned." });
     if (booking.TechnicianId == request.TechnicianId)
         return Conflict(new { message = "This technician is already assigned to the booking." });

     var technician = await db.TechnicianProfiles.Include(x => x.User)
         .SingleOrDefaultAsync(x => x.UserId == request.TechnicianId && x.Status == TechnicianStatus.Approved);
     if (technician is null || !technician.IsOnline || !technician.User.IsActive)
         return BadRequest(new { message = "Choose an active, approved technician who is online." });
     if (!await db.TechnicianCoverageAreas.AnyAsync(x => x.TechnicianId == technician.UserId && x.ServiceArea.IsActive && x.ServiceArea.CityMunicipality == booking.Address.CityMunicipality && x.ServiceArea.Province == booking.Address.Province))
         return BadRequest(new { message = "Technician does not cover this city." });
     if (!await db.TechnicianSkills.AnyAsync(x => x.TechnicianId == technician.UserId && x.ServiceId == booking.ServiceId))
         return BadRequest(new { message = "Technician is not qualified for this service category." });

     var local = booking.ScheduledAt.AddHours(8);
     var time = TimeOnly.FromDateTime(local);
     if (!await db.TechnicianAvailabilities.AnyAsync(x => x.TechnicianId == technician.UserId && x.IsAvailable && x.DayOfWeek == (int)local.DayOfWeek && x.StartTime <= time && x.EndTime >= time))
         return Conflict(new { message = "Technician is not available at the requested appointment time." });
     var from = booking.ScheduledAt.AddHours(-2);
     var to = booking.ScheduledAt.AddHours(2);
     if (await db.Bookings.AnyAsync(x => x.Id != id && x.TechnicianId == technician.UserId && x.Status != BookingStatus.Cancelled && x.ScheduledAt >= from && x.ScheduledAt <= to))
         return Conflict(new { message = "Technician already has a nearby booking." });

     if (booking.TechnicianId is not null)
         db.Notifications.Add(new Notification { UserId = booking.TechnicianId, Title = "Booking reassigned", Message = $"FIXIT booking {booking.Reference} was reassigned by an administrator." });
     booking.TechnicianId = technician.UserId;
     booking.Status = BookingStatus.Accepted;
     db.BookingAssignments.Add(new BookingAssignment { BookingId = id, TechnicianId = technician.UserId, AssignedById = Actor, Note = request.Reason.Trim() });
     db.BookingStatusHistories.Add(new BookingStatusHistory { BookingId = id, Status = booking.Status, ChangedByUserId = Actor, Note = "Administrator assigned technician: " + request.Reason.Trim() });
     db.AuditLogs.Add(new AuditLog { ActorId = Actor, Action = "booking.assign", EntityType = "Booking", EntityId = id.ToString(), Details = request.Reason.Trim() });
     db.Notifications.Add(new Notification { UserId = technician.UserId, Title = "New FIXIT appointment", Message = $"Booking {booking.Reference} has been assigned to you." });
     await db.SaveChangesAsync();
     await transaction.CommitAsync();
     return Ok(new { status = booking.Status.ToString() });
 }
 [HttpPost("services")] public async Task<IActionResult> CreateService(ServiceUpsert r){var s=new Service{Name=r.Name.Trim(),Description=r.Description.Trim(),BasePrice=r.BasePrice,IsActive=r.IsActive};db.Services.Add(s);await db.SaveChangesAsync();return Created($"/api/services/{s.Id}",new{id=s.Id});}
 [HttpPut("services/{id:int}")] public async Task<IActionResult> UpdateService(int id,ServiceUpsert r){var s=await db.Services.FindAsync(id);if(s is null)return NotFound();s.Name=r.Name.Trim();s.Description=r.Description.Trim();s.BasePrice=r.BasePrice;s.IsActive=r.IsActive;db.AuditLogs.Add(new(){ActorId=Actor,Action="service.update",EntityType="Service",EntityId=id.ToString()});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("services")] public async Task<IActionResult> Services()=>Ok(await db.Services.AsNoTracking().OrderBy(s=>s.Name).ToListAsync());
 [HttpGet("areas")] public async Task<IActionResult> Areas()=>Ok(await db.ServiceAreas.AsNoTracking().OrderBy(a=>a.Province).ThenBy(a=>a.CityMunicipality).ToListAsync());
 [HttpPost("areas")] public async Task<IActionResult> AddArea(AreaUpsert r){var a=new ServiceArea{CityMunicipality=r.CityMunicipality.Trim(),Province=r.Province.Trim(),IsActive=r.IsActive};db.ServiceAreas.Add(a);await db.SaveChangesAsync();return Created($"/api/admin/areas/{a.Id}",new{id=a.Id});}
 [HttpPut("areas/{id:int}")] public async Task<IActionResult> UpdateArea(int id,AreaUpsert r){var a=await db.ServiceAreas.FindAsync(id);if(a is null)return NotFound();a.CityMunicipality=r.CityMunicipality.Trim();a.Province=r.Province.Trim();a.IsActive=r.IsActive;db.AuditLogs.Add(new(){ActorId=Actor,Action="service-area.update",EntityType="ServiceArea",EntityId=id.ToString()});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("settings")] public async Task<IActionResult> Settings()=>Ok(new{platformFeePercent=(await db.PlatformSettings.FindAsync("PlatformFeePercent"))?.NumericValue??15m,cancellationHours=(await db.PlatformSettings.FindAsync("CancellationHours"))?.NumericValue??24m});
 [HttpPut("settings")] public async Task<IActionResult> UpdateSettings(PlatformSettingsUpdate r){var fee=await db.PlatformSettings.FindAsync("PlatformFeePercent");var cancellation=await db.PlatformSettings.FindAsync("CancellationHours");if(fee is null||cancellation is null)return StatusCode(503,new{message="Platform settings have not been initialized. Apply the database migration."});fee.NumericValue=r.PlatformFeePercent;cancellation.NumericValue=r.CancellationHours;db.AuditLogs.Add(new(){ActorId=Actor,Action="platform.settings.update",EntityType="PlatformSetting",EntityId="PlatformFeePercent,CancellationHours",Details=$"fee={r.PlatformFeePercent}; cancellationHours={r.CancellationHours}"});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("disputes")] public async Task<IActionResult> Disputes()=>Ok(await db.Disputes.AsNoTracking().OrderByDescending(d=>d.CreatedAt).Select(d=>new{d.Id,d.BookingId,booking=d.Booking.Reference,d.Description,status=d.Status.ToString(),d.CreatedAt,reportedBy=d.ReportedById}).ToListAsync());
 [HttpGet("tickets")] public async Task<IActionResult> Tickets()=>Ok(await db.SupportTickets.AsNoTracking().OrderByDescending(t=>t.CreatedAt).Select(t=>new{t.Id,t.UserId,user=t.UserId, t.Subject,t.Message,status=t.Status.ToString(),t.CreatedAt}).ToListAsync());
 [HttpGet("reviews")] public async Task<IActionResult> Reviews()=>Ok(await db.Reviews.AsNoTracking().OrderByDescending(r=>r.CreatedAt).Select(r=>new{r.Id,r.Rating,r.Comment,state=r.State.ToString(),booking=r.Booking.Reference,customer=r.CustomerId}).ToListAsync());
 [HttpPost("reviews/{id:int}/moderate")] public async Task<IActionResult> Moderate(int id,ReviewDecisionRequest r){var review=await db.Reviews.FindAsync(id);if(review is null)return NotFound();review.State=r.Visible?ReviewState.Visible:ReviewState.Hidden;db.AuditLogs.Add(new(){ActorId=Actor,Action="review.moderate",EntityType="Review",EntityId=id.ToString(),Details=r.Reason});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("refunds")] public async Task<IActionResult> Refunds()=>Ok(await db.RefundRequests.AsNoTracking().OrderByDescending(r=>r.CreatedAt).Select(r=>new{r.Id,r.PaymentId,r.Amount,r.Reason,r.Approved,r.CreatedAt,booking=r.Payment.Booking.Reference,paymentStatus=r.Payment.Status.ToString()}).ToListAsync());
 [HttpPost("refunds/{id:int}/decision")] public async Task<IActionResult> RefundDecision(int id,RefundDecisionRequest r){await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var refund=await db.RefundRequests.Include(x=>x.Payment).SingleOrDefaultAsync(x=>x.Id==id);if(refund is null)return NotFound();if(refund.Approved is not null)return Conflict();if(r.Approve&&refund.Payment.Status!=PaymentStatus.Paid)return Conflict(new{message="This payment is no longer eligible for a demo refund."});refund.Approved=r.Approve;refund.ReviewedById=Actor;if(r.Approve)refund.Payment.Status=PaymentStatus.Refunded;db.AuditLogs.Add(new(){ActorId=Actor,Action=r.Approve?"refund.approve":"refund.reject",EntityType="RefundRequest",EntityId=id.ToString(),Details=r.Reason});await db.SaveChangesAsync();await transaction.CommitAsync();return NoContent();}
 [HttpGet("deletion-requests")] public async Task<IActionResult> DeletionRequests()=>Ok(await db.PrivacyRequests.AsNoTracking().Where(r=>r.Approved==null).OrderBy(r=>r.CreatedAt).Select(r=>new{r.Id,r.UserId,email=r.User.Email,r.Reason,r.CreatedAt}).ToListAsync());
 [HttpPost("deletion-requests/{id:int}/decision")] public async Task<IActionResult> DeletionDecision(int id,RefundDecisionRequest r){var request=await db.PrivacyRequests.Include(x=>x.User).SingleOrDefaultAsync(x=>x.Id==id);if(request is null)return NotFound();if(request.Approved is not null)return Conflict();request.Approved=r.Approve;request.ReviewedById=Actor;request.ReviewedAt=DateTime.UtcNow;if(r.Approve){var u=request.User;u.IsActive=false;u.Email=$"deleted-{Guid.NewGuid():N}@invalid.fixit";u.NormalizedEmail=u.Email.ToUpperInvariant();u.UserName=u.Email;u.NormalizedUserName=u.Email.ToUpperInvariant();u.PhoneNumber=null;u.FirstName="Deleted";u.LastName="Account";var addresses=await db.Addresses.Where(a=>a.CustomerId==u.Id).ToListAsync();foreach(var a in addresses){a.Street="[removed]";a.Barangay="[removed]";a.CityMunicipality="[removed]";a.Province="[removed]";a.Region="[removed]";a.Landmark=null;}await users.UpdateSecurityStampAsync(u);}db.AuditLogs.Add(new(){ActorId=Actor,Action=r.Approve?"privacy.deletion.approve":"privacy.deletion.reject",EntityType="PrivacyRequest",EntityId=id.ToString(),Details=r.Reason});await db.SaveChangesAsync();return NoContent();}
 [HttpPost("tickets/{id:int}/status")] public async Task<IActionResult> SetTicketStatus(int id,[FromQuery]TicketStatus status){var t=await db.SupportTickets.FindAsync(id);if(t is null)return NotFound();t.Status=status;db.AuditLogs.Add(new(){ActorId=Actor,Action="support.ticket.status",EntityType="SupportTicket",EntityId=id.ToString()});await db.SaveChangesAsync();return NoContent();}
 [HttpPost("disputes/{id:int}/resolve")] public async Task<IActionResult> ResolveDispute(int id,DisputeResolutionRequest r){var d=await db.Disputes.SingleOrDefaultAsync(x=>x.Id==id);if(d is null)return NotFound();d.Status=r.Resolved?TicketStatus.Resolved:TicketStatus.InProgress;d.Resolution=r.Resolution.Trim();db.AuditLogs.Add(new(){ActorId=Actor,Action="dispute.resolve",EntityType="Dispute",EntityId=id.ToString(),Details=r.Resolution});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("audit")] public async Task<IActionResult> Audit()=>Ok(await db.AuditLogs.AsNoTracking().OrderByDescending(a=>a.CreatedAt).Take(500).ToListAsync());
}
